Change the code so that rows where Category is DAMAGE go to a new table called damage, HEALS to a table called heals, and MITIGATION to a table called mitigation.

How many observations are in each new table?


Save the full table with Category as ma505.ow_cat. We will use it in the next exercise.




libname ma505 "~";    /* skip if your autoexec does this */

data ma505.ow_cat damage heals mitigation;
    set ma505.ow_stats;
    length Category $ 10;
    HighestVal = max(Damage, Heals, Mitigation);
    if HighestVal = Damage then do;
        Category = "DAMAGE";
        output damage;
    end;
    else if HighestVal = Heals then do;
        Category = "HEALS";
        output heals;
    end;
    else do;
        Category = "MITIGATION";
        output mitigation;
    end;
    output ma505.ow_cat;    /* every row also goes to the full table */
run;

/* how many rows in each category? */
proc freq data=ma505.ow_cat;
    tables Category;
run;


